def copiar_prazos(apps, schema_editor):
    """Datas de início e prazo passam a texto livre (D-34)."""
    Procura = apps.get_model("procuras", "Procura")
    for p in Procura.objects.all():
        p.quando_iniciou = p.data_inicio.strftime("%d/%m/%Y") if p.data_inicio else ""
        p.prazo_aquisicao = p.prazo_compra.strftime("%d/%m/%Y") if p.prazo_compra else ""
        p.save(update_fields=["quando_iniciou", "prazo_aquisicao"])


